"""Positive evidence for modern daily rewards and the seasonal lobby announcement."""
import base64
from functools import lru_cache
import cv2
import numpy as np
TITLE = ''
FACE = ''
PIN = ''
@lru_cache(maxsize=32)
def _glyph(encoded,height):
    a=cv2.imdecode(np.frombuffer(base64.b64decode(encoded),np.uint8),0)
    return cv2.resize(a,(max(2,round(a.shape[1]*height/720)),max(2,round(a.shape[0]*height/720))))

def _match(image,glyph):
    if not image.size or any(image.shape[i]<glyph.shape[i] for i in (0,1)):return False
    return cv2.minMaxLoc(cv2.matchTemplate(image,glyph,cv2.TM_CCOEFF_NORMED))[1]>=.92

def modern_daily_reward(frame):
    if frame is None or frame.ndim!=3 or frame.shape[2]!=3:return False
    h,w=frame.shape[:2]
    crop=frame[:round(h*.16),:round(w*.35)]
    white=np.all(crop>205,axis=2).astype(np.uint8)*255
    if not _match(white,_glyph(TITLE,h)):return False
    # The large star is independent evidence; DAILY WINS alone is insufficient.
    small=cv2.resize(frame,(320,180),interpolation=cv2.INTER_AREA)
    dark=np.all(small<50,axis=2).astype(np.uint8)*255
    contours,_=cv2.findContours(dark,cv2.RETR_LIST,cv2.CHAIN_APPROX_SIMPLE)
    stars=[]
    for c in contours:
        x,y,bw,bh=cv2.boundingRect(c);area=cv2.contourArea(c)
        vertices=len(cv2.approxPolyDP(c,.025*cv2.arcLength(c,True),True))
        if (85<=bw<=120 and 90<=bh<=130 and 40<=x<=220 and 35<=y<=65
                and 5400<=area<=10000 and 6<=vertices<=16):
            if x<160<x+bw:return True
            stars.append((x,y,bw,bh))
    # Double rewards place two matching stars on either side of the centre.
    # One off-centre silhouette must not authorize a reward action by itself.
    for a in stars:
        for b in stars:
            if (a[0]+a[2]<160<b[0] and abs(a[1]-b[1])<10
                    and abs(a[2]-b[2])<12 and abs(a[3]-b[3])<12):return True
    return False

def seasonal_announcement_dismiss_position(frame):
    if frame is None or frame.ndim!=3 or frame.shape[2]!=3:return None
    h,w=frame.shape[:2]
    button=frame[round(h*.82):round(h*.91),round(w*.41):round(w*.59)].astype(np.int16)
    if not button.size or ((button[:,:,2]>160)&(button[:,:,0]<80)&(button[:,:,1]>60)).mean()<.35:return None
    margin=frame[round(h*.25):round(h*.65),:round(w*.08)]
    if not margin.size or margin.mean()>85:return None
    gray=cv2.cvtColor(frame,cv2.COLOR_RGB2GRAY)
    for encoded,bounds in [(FACE,(.38,.30,.65,.53)),(PIN,(.64,.10,.86,.42))]:
        x1,y1,x2,y2=bounds;roi=gray[round(h*y1):round(h*y2),round(w*x1):round(w*x2)]
        if not _match(roi,_glyph(encoded,h)):return None
    # The verified announcement closes through its dimmed outside margin.
    # Avoid its GO button, which navigates into a different game event.
    return round(w*.05),round(h*.5)

XP_TITLE = ''
XP_CARD = ''

def xp_doubler_reward(frame):
    if frame is None or frame.ndim!=3 or frame.shape[2]!=3:return False
    h,w=frame.shape[:2]
    background=frame[round(h*.80):round(h*.96),round(w*.08):round(w*.92)].astype(np.float32)
    if not background.size:return False
    blue=(background[:,:,2]>background[:,:,0]*1.35)&(background[:,:,2]>background[:,:,1]*1.2)
    if blue.mean()<.9:return False
    for encoded,bounds in [(XP_TITLE,(.28,.12,.72,.28)),(XP_CARD,(.4,.35,.6,.66))]:
        x1,y1,x2,y2=bounds;roi=frame[round(h*y1):round(h*y2),round(w*x1):round(w*x2)]
        white=np.all(roi>205,axis=2).astype(np.uint8)*255
        if not _match(white,_glyph(encoded,h)):return False
    return True

POINTS_TITLE = ''
POINTS_ICON = ''
GADGET_TITLE = ''
GADGET_OUTLINE = ''

def points_reward(frame):
    if frame is None or frame.ndim!=3 or frame.shape[2]!=3:return False
    h,w=frame.shape[:2];background=frame[round(h*.85):round(h*.96),round(w*.08):round(w*.92)].astype(np.float32)
    if not background.size:return False
    purple=(background[:,:,2]>background[:,:,0]*1.2)&(background[:,:,2]>background[:,:,1]*1.15)&(background[:,:,0]>35)
    if purple.mean()<.9:return False
    header=frame[round(h*.14):round(h*.3),round(w*.28):round(w*.72)]
    if not _match(np.all(header>205,axis=2).astype(np.uint8)*255,_glyph(POINTS_TITLE,h)):return False
    icon=frame[round(h*.40):round(h*.66),round(w*.4):round(w*.6)]
    return _match(cv2.cvtColor(icon,cv2.COLOR_RGB2GRAY),_glyph(POINTS_ICON,h))

def gadget_reward(frame):
    if frame is None or frame.ndim!=3 or frame.shape[2]!=3:return False
    h,w=frame.shape[:2];header=frame[round(h*.18):round(h*.35),round(w*.5):round(w*.88)]
    if not _match(np.all(header>205,axis=2).astype(np.uint8)*255,_glyph(GADGET_TITLE,h)):return False
    # The receipt has a wide dark description card with bright cyan text.
    card=frame[round(h*.445):round(h*.66),round(w*.56):round(w*.95)].astype(np.int16)
    if not card.size:return False
    dark=(card.mean(axis=2)<65).mean();cyan=((card[:,:,0]<100)&(card[:,:,1]>170)&(card[:,:,2]>170)).mean()
    if dark<.5 or cyan<.04:return False
    roi=frame[round(h*.25):round(h*.75),round(w*.05):round(w*.35)]
    green=((roi[:,:,1]>100)&(roi[:,:,0]<85)&(roi[:,:,2]<85)).astype(np.uint8)*255
    contours,_=cv2.findContours(green,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE)
    # Fill the outline so any gadget's interior symbol can vary independently.
    mask=np.zeros_like(green)
    for c in contours:
        if cv2.contourArea(c)>h*h*.025:cv2.drawContours(mask,[c],-1,255,-1)
    return _match(mask,_glyph(GADGET_OUTLINE,h))

def credits_reward(frame):
    """A credits receipt needs its title, central token glyph and blue backdrop."""
    if frame is None or frame.ndim != 3 or frame.shape[2] != 3:
        return False
    h, w = frame.shape[:2]
    background = frame[round(h*.85):round(h*.96), round(w*.08):round(w*.92)].astype(np.float32)
    if not background.size:
        return False
    blue = (background[:,:,2] > background[:,:,0]*1.35) & (background[:,:,2] > background[:,:,1]*1.2)
    if blue.mean() < .9:
        return False
    header = frame[round(h*.18):round(h*.35), round(w*.28):round(w*.72)]
    if not _match(np.all(header > 205, axis=2).astype(np.uint8)*255, _glyph(CREDITS_TITLE, h)):
        return False
    icon = frame[round(h*.4):round(h*.72), round(w*.38):round(w*.65)]
    cyan = (icon[:,:,0] < 100) & (icon[:,:,1] > 150) & (icon[:,:,2] > 180)
    if not cyan.size or cyan.mean() < .12:
        return False
    return _match(cv2.cvtColor(icon, cv2.COLOR_RGB2GRAY), _glyph(CREDITS_ICON, h))

CREDITS_TITLE = ''
CREDITS_ICON = ''
